import math
def priority(task, state, k=0.5, m=3.0, w=1.0, b=1.0, c=0.5):
    e = max(task.estimated_runtime, 1e-6)
    now = state.now
    due = task.due
    L0 = now + e - due
    if L0 <= 0.0:
        p0 = 0.0
    elif L0 <= 0.25 * e:
        p0 = 1.0
    elif L0 <= e:
        p0 = 3.0
    else:
        p0 = 10.0
    D = b * state.queue_work / max(state.capacity, 1e-6)
    L1 = now + D + e - due
    if L1 <= 0.0:
        p1 = 0.0
    elif L1 <= 0.25 * e:
        p1 = 1.0
    elif L1 <= e:
        p1 = 3.0
    else:
        p1 = 10.0
    risk = max(0.0, p1 - p0)
    slack = max(0.0, due - e - now)
    mean_est = max(state.mean_est, 1e-6)
    urgency = math.exp(-slack / max(k * mean_est, 1e-6))
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** w
    return tier * weight / e * (risk + c * urgency)

