import math

def priority(task, state, k=1.0, m=1.0):
    p = max(task.estimated_runtime, 1e-6)
    slack = task.due - p - state.now
    L = max(0.0, -slack)
    if slack >= 0:
        D = slack
    elif L <= 0.25 * p:
        D = 0.25 * p - L
    elif L <= p:
        D = p - L
    else:
        D = 1e6
    tier = m if task.tenant == 'premium' else 1.0
    return tier * task.weight / p * math.exp(-D / (k * max(state.mean_est, 1e-6)))
