import math
def priority(task, state, k=1.0, m=3.0, rho=0.0, age=0.02, small=1.5, medium=3.0, hopeless=0.05, fit=0.0, ta=1.0, tv=1.0, ts=1.0):
    e = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    now = state.now
    mean = max(state.mean_est, 1e-6)
    lat_ratio = (now + e - task.due) / e
    if lat_ratio <= 0.0:
        risk = 1.0
    elif lat_ratio <= 0.25:
        risk = small
    elif lat_ratio <= 1.0:
        risk = medium
    else:
        risk = hopeless
    slack = max(0.0, task.due - e - now)
    atc = math.exp(-slack / max(k * mean, 1e-6))
    if task.task_type == 'alignment':
        tf = ta
    elif task.task_type == 'variant_calling':
        tf = tv
    else:
        tf = ts
    tier = m if task.tenant == 'premium' else 1.0
    fitfac = (1.0 + fit) if need <= state.free else 1.0
    wait = max(0.0, now - task.release)
    agefac = 1.0 + age * wait / e
    return tier * tf * max(task.weight, 1e-6) / e * atc * risk * agefac * fitfac / (need ** rho)
